function setupCardCheckout(){
  const payment=e('#payment');
  const send=e('#send');
  const panel=e('#caseiraoCardQuote');
  const checkout=send.closest('.sheet');
  const total=e('#checkoutFooterTotal');
  const totalLabel=total.previousElementSibling;
  let timer;
  let revision=0;
  let quote=null;
  let wasSelected=false;
  let ordinaryTotal=total.textContent;

  const selected=()=>payment.value===caseiraoPayment;
  const current=number=>number===revision&&panel.isConnected&&selected();
  function message(value){
    panel.hidden=false;
    panel.textContent=value;
  }

  async function refresh(){
    clearTimeout(timer);
    if(!selected()||!panel.isConnected)return;
    const revisionAtStart=++revision;
    quote=null;
    try{
      const token=window.caseiraoCard?.token();
      const name=e('#name').value.trim();
      const phone=i(e('#phone').value);
      if(!token)throw new Error('Abra Meu Cartão Caseirão para acessar seu cartão.');
      if(name.length<2||phone.length<10)throw new Error('Preencha seu nome e WhatsApp para consultar o total no Cartão Caseirão.');
      const payload=checkoutPayload(name,phone,caseiraoPayment,readSchedule());
      if(payload.cashback_to_use>0)throw new Error('Remova o cashback para consultar o Cartão Caseirão.');
      message('Calculando produtos, juros e total da fatura…');
      send.disabled=true;
      const result=await N('create-order',{...payload,card_token:token,card_quote:true});
      if(!current(revisionAtStart))return;
      window.caseiraoCard.describe(result.quote,result.breakdown,panel);
      quote={payload:JSON.stringify(payload),values:result.quote};
      totalLabel.textContent='Total da fatura';
      total.textContent=a(result.quote.total/100);
      send.textContent='Confirmar compra no Cartão Caseirão';
    }catch(error){
      if(!current(revisionAtStart))return;
      message(error.message||'Não foi possível calcular o total da fatura.');
      send.textContent='Consultar total no Cartão Caseirão';
    }finally{
      if(current(revisionAtStart))send.disabled=false;
    }
  }

  function update(delay=0){
    clearTimeout(timer);
    ++revision;
    quote=null;
    if(!selected()){
      if(wasSelected){
        panel.hidden=true;
        totalLabel.textContent='Total do pedido';
        total.textContent=ordinaryTotal;
        send.textContent=e('#scheduleMode')?.value==='schedule'?'Solicitar agendamento':'Enviar pedido';
        send.disabled=false;
      }
      wasSelected=false;
      return;
    }
    if(!panel.isConnected)return;
    if(!wasSelected)ordinaryTotal=total.textContent;
    wasSelected=true;
    totalLabel.textContent='Total da fatura';
    total.textContent='—';
    message('Conferindo o total da fatura…');
    send.textContent='Consultando total…';
    send.disabled=true;
    if(delay)timer=setTimeout(refresh,delay);
    else void refresh();
  }

  const fields=new Set(['name','phone','street','number','hood','complement','reference','coupon','notes','scheduleMode','scheduledFor']);
  checkout.addEventListener('input',event=>{
    if(selected()&&fields.has(event.target.id))update(300);
  });
  checkout.addEventListener('change',event=>{
    if(event.target.id==='payment')return;
    if(selected()&&fields.has(event.target.id))update(300);
  });
  payment.addEventListener('change',()=>update());
  update();
  return {
    quoteFor:payload=>quote?.payload===JSON.stringify(payload)?quote.values:null,
    refresh,
    pricesChanged:value=>{if(value!==undefined)ordinaryTotal=value;if(selected())update(300);}
  };
}
